static void test_verify(void) {
    TEST_SUITE("p256_ecdsa_verify — accepts real cryptography-issued signatures");
    for (int i = 0; i < NVERIFY; i++) {
        int64_t ok = p256_ecdsa_verify(VERIFIES[i].hash, VERIFIES[i].r, VERIFIES[i].s,
                                        VERIFIES[i].qx, VERIFIES[i].qy);
        ASSERT_EQ("valid signature accepted", 1, ok);
    }
}

static void test_verify_rejects_tampering(void) {
    TEST_SUITE("p256_ecdsa_verify — rejects tampered signatures");
    for (int i = 0; i < 5; i++) {
        uint8_t r[32];
        memcpy(r, VERIFIES[i].r, 32);
        r[31] ^= 0x01;  // flip a bit in r
        int64_t ok = p256_ecdsa_verify(VERIFIES[i].hash, r, VERIFIES[i].s,
                                        VERIFIES[i].qx, VERIFIES[i].qy);
        ASSERT_EQ("tampered r rejected", 0, ok);

        uint8_t s[32];
        memcpy(s, VERIFIES[i].s, 32);
        s[31] ^= 0x01;
        ok = p256_ecdsa_verify(VERIFIES[i].hash, VERIFIES[i].r, s,
                                VERIFIES[i].qx, VERIFIES[i].qy);
        ASSERT_EQ("tampered s rejected", 0, ok);

        uint8_t h[32];
        memcpy(h, VERIFIES[i].hash, 32);
        h[0] ^= 0x01;
        ok = p256_ecdsa_verify(h, VERIFIES[i].r, VERIFIES[i].s,
                                VERIFIES[i].qx, VERIFIES[i].qy);
        ASSERT_EQ("tampered hash rejected", 0, ok);
    }

    // r == 0 and s == 0 must be rejected outright.
    uint8_t zero[32] = {0};
    int64_t ok = p256_ecdsa_verify(VERIFIES[0].hash, zero, VERIFIES[0].s,
                                    VERIFIES[0].qx, VERIFIES[0].qy);
    ASSERT_EQ("r == 0 rejected", 0, ok);
    ok = p256_ecdsa_verify(VERIFIES[0].hash, VERIFIES[0].r, zero,
                            VERIFIES[0].qx, VERIFIES[0].qy);
    ASSERT_EQ("s == 0 rejected", 0, ok);
}

int main(void) {
    test_verify();
    test_verify_rejects_tampering();
    test_summary();
    return 0;
}
